public enum AdminPropertyType {
  /// <summary>
  /// The device name that appears on the network. Limited to 16 characters.
  /// </summary>
  [pbr::OriginalName("DEVICE_NAME")] DeviceName = 0,
  /// <summary>
  /// Used for documentation. Limited to 32 characters.
  /// </summary>
  [pbr::OriginalName("PROJECT_NAME")] ProjectName = 1,
  /// <summary>
  /// Used for calculating astronomical sunrise / sunset.
  /// </summary>
  [pbr::OriginalName("LONGITUDE")] Longitude = 2,
  /// <summary>
  /// Used for calculating astronomical sunrise / sunset.
  /// </summary>
  [pbr::OriginalName("LATITUDE")] Latitude = 3,
  /// <summary>
  /// Used for calculating astronomical sunrise / sunset.
  /// </summary>
  [pbr::OriginalName("LOCAL_UTC_OFFSET")] LocalUtcOffset = 4,
  /// <summary>
  /// Used for calculating astronomical sunrise / sunset.
  /// </summary>
  [pbr::OriginalName("DAYLIGHT_SAVINGS")] DaylightSavings = 5,
  /// <summary>
  /// Whether or not to poll the current level of DALI devices to keep an in-memory cache up-to-date.
  /// </summary>
  [pbr::OriginalName("POLL_ACTIVE")] PollActive = 6,
  /// <summary>
  /// Whether or not the device should use a static IP or expect a DHCP server to provide it with an IP.
  /// </summary>
  [pbr::OriginalName("DHCP_ENABLED")] DhcpEnabled = 7,
  /// <summary>
  /// The static IP address to use if DHCP_ENABLED is FALSE.
  /// </summary>
  [pbr::OriginalName("IP_ADDR")] IpAddr = 8,
  /// <summary>
  /// The MAC Address of the device. Expected format: [40:D8:55:1B:XX:XX]
  /// </summary>
  [pbr::OriginalName("MAC_ADDR")] MacAddr = 9,
  /// <summary>
  /// The IP address of the gateway for the network this device will be installed on.
  /// </summary>
  [pbr::OriginalName("GATEWAY_IP")] GatewayIp = 10,
  /// <summary>
  /// Contains numerous properties such as DHCP, NTP, Gateway, IP, MAC
  /// </summary>
  [pbr::OriginalName("NETWORK_PROPERTIES")] NetworkProperties = 11,
  /// <summary>
  /// Contains numerous properties such as Device Name (documentation only; not network hostname), Project Name, Latitude, Longitude, UTC Offset, DLS, Polling
  /// </summary>
  [pbr::OriginalName("SYSTEM_PROPERTIES")] SystemProperties = 12,
  /// <summary>
  /// Allows you to specify the daughterboards installed in the device [NONE, DALI, DMX, DMX_IN]
  /// </summary>
  [pbr::OriginalName("CONTROLLER_LINES")] ControllerLines = 13,
  /// <summary>
  /// Allows you to request a reset to default values for all data stored in EEPROM
  /// </summary>
  [pbr::OriginalName("EEPROM_FULL_CHIP")] EepromFullChip = 14,
  /// <summary>
  /// Allows you to request a reset to default values for the Config Data stored in EEPROM
  /// </summary>
  [pbr::OriginalName("CONFIG_DATA")] ConfigData = 15,
  /// <summary>
  /// Allows you to request a reset to default values for the Spektra Data stored in EEPROM
  /// </summary>
  [pbr::OriginalName("SPEKTRA_DATA")] SpektraData = 16,
  /// <summary>
  /// Can be used to request the Device Status: Temperature and Battery Voltage
  /// </summary>
  [pbr::OriginalName("DEVICE_STATUS")] DeviceStatus = 17,
  /// <summary>
  /// Can be used to request the Config Status: Active Alarm, List States, Sensor States, Burn-in States
  /// </summary>
  [pbr::OriginalName("CONFIG_STATUS")] ConfigStatus = 18,
  /// <summary>
  /// Get or Set the RTC time on the device
  /// </summary>
  [pbr::OriginalName("DEVICE_TIME")] DeviceTime = 19,
  /// <summary>
  /// Allows you to Get or Set the NTP parameters (i.e. NTP Server) used for maintaining the RTC via NTP updates.
  /// </summary>
  [pbr::OriginalName("NTP_DETAILS")] NtpDetails = 20,
  /// <summary>
  /// Provides actions for DALI Sensor control: "ADD" to un-mute all. "REMOVE" to mute all. "RESET" to clear all (unprogram).
  /// </summary>
  [pbr::OriginalName("DALI_SENSORS")] DaliSensors = 21,
  /// <summary>
  /// Allows you to Get or Set the "Secure Session" status of the device
  /// </summary>
  [pbr::OriginalName("SECURE_SESSION")] SecureSession = 22,
  /// <summary>
  /// Allows you to request a Nonce to perform a Secure Login
  /// </summary>
  [pbr::OriginalName("NONCE")] Nonce = 23,
  /// <summary>
  /// The type of DALI frame (24 or 25-bit) for eDALI packets to/from motion sensors
  /// </summary>
  [pbr::OriginalName("DALI_SENSOR_TYPE")] DaliSensorType = 24,
  /// <summary>
  /// Will reboot the device when used with the 'RUN' AdminCommandType
  /// </summary>
  [pbr::OriginalName("DEVICE_REBOOT")] DeviceReboot = 25,
  /// <summary>
  /// Will reset the system logs when used with a 'RESET' AdminCommandType
  /// </summary>
  [pbr::OriginalName("SYSTEM_LOGGING")] SystemLogging = 26,
  /// <summary>
  /// The Subnet of the Device
  /// </summary>
  [pbr::OriginalName("SUBNET")] Subnet = 27,
  /// <summary>
  /// The Primary and Secondary DNS
  /// </summary>
  [pbr::OriginalName("DNS")] Dns = 28,
  /// <summary>
  /// Whether or not the UDP Link state is active
  /// </summary>
  [pbr::OriginalName("LINK")] Link = 29,
  /// <summary>
  /// Type of Link to enable, based on ReadType
  /// </summary>
  [pbr::OriginalName("LINK_TYPE")] LinkType = 30,
  /// <summary>
  /// Link Index Mask for above
  /// </summary>
  [pbr::OriginalName("LINK_MASK")] LinkMask = 31,
  /// <summary>
  /// Netmask for Link to create Network groups for UDP messaging
  /// </summary>
  [pbr::OriginalName("LINK_NETMASK")] LinkNetmask = 32,
  /// <summary>
  /// The tolerance for DALI RX (where 10 is 10% above and below nominal half bit time of 416us)
  /// </summary>
  [pbr::OriginalName("DALI_RX_TOLERANCE")] DaliRxTolerance = 33,
  /// <summary>
  /// Default value is 416us
  /// </summary>
  [pbr::OriginalName("DALI_TX_HALF_BIT_TIME")] DaliTxHalfBitTime = 34,
  /// <summary>
  /// DMX Timing (I.e. 44Hz)
  /// </summary>
  [pbr::OriginalName("DMX_TIMING")] DmxTiming = 35,
  /// <summary>
  /// DMX Line Properties. Channel Mapping, 16 bit, slot count
  /// </summary>
  [pbr::OriginalName("DMX_PROPERTIES")] DmxProperties = 36,
  /// <summary>
  /// GET-only. Returns per-task stack high-water-marks, system-stack HWM, and SRAM/CCMRAM static-section usage. Use with the 'GET' AdminCommandType. Used for tuning FreeRTOS task stack sizes and monitoring runtime RAM headroom.
  /// </summary>
  [pbr::OriginalName("MEMORY_DIAGNOSTICS")] MemoryDiagnostics = 37,
  /// <summary>
  /// GET-only. Returns Ethernet PHY register snapshot, Ethernet MAC counters, resolved link state, and a ring buffer of recent link-state transitions. Use with the 'GET' AdminCommandType. Used to diagnose link/auto-negotiation/duplex-mismatch issues without an SD card.
  /// </summary>
  [pbr::OriginalName("ETHERNET_DIAGNOSTICS")] EthernetDiagnostics = 38,
  /// <summary>
  /// GET-only. Per-line readout of configured-vs-probed daughterboard type plus a coarse OK/FAULTY/EMPTY/MISCONFIGURED verdict. Briefly perturbs each line (a DALI half-bit pulse and/or a DMX RX-mode window) — fire on demand, not on a hot loop. Use with the 'GET' AdminCommandType.
  /// </summary>
  [pbr::OriginalName("LINE_DIAGNOSTICS")] LineDiagnostics = 39,
  /// <summary>
  /// GET-only. RTC/NTP/DST observability: LSE crystal ppm measurement, lifetime NTP success/failure counts, last sync details, time-set audit trail, backup-domain boot counter, DST visibility. Use with the 'GET' AdminCommandType.
  /// </summary>
  [pbr::OriginalName("TIME_DIAGNOSTICS")] TimeDiagnostics = 40,
  /// <summary>
  /// GET/SET. Enable/disable the temperature-driven smooth calibration of the RTC. Persisted in BKPSRAM (reset on battery loss). Default 1.
  /// </summary>
  [pbr::OriginalName("RTC_TEMP_COMP_ENABLED")] RtcTempCompEnabled = 41,
  /// <summary>
  /// GET/SET. When enabled (override flag in PayloadMessage), the RTC smooth calibration is set to a fixed signed ppm value at every hour boundary, bypassing temp comp. Persisted in BKPSRAM.
  /// </summary>
  [pbr::OriginalName("RTC_PPM_MANUAL_OVERRIDE")] RtcPpmManualOverride = 42,
  /// <summary>
  /// RUN. Triggers an immediate NTP sync attempt.
  /// </summary>
  [pbr::OriginalName("NTP_FORCE_SYNC")] NtpForceSync = 43,
  /// <summary>
  /// GET/SET. Override the NTP poll period. 0 means use the existing NTP_DETAILS.NTPTimeout from config. Non-zero is persisted in BKPSRAM.
  /// </summary>
  [pbr::OriginalName("NTP_POLL_PERIOD_SECONDS")] NtpPollPeriodSeconds = 44,
  /// <summary>
  /// GET/SET. NTP corrections whose |delta| exceeds this value are rejected (treated as a sanity-check failure). Default 3600 (1 hour). Persisted in BKPSRAM.
  /// </summary>
  [pbr::OriginalName("NTP_MAX_ACCEPTABLE_DELTA_SECONDS")] NtpMaxAcceptableDeltaSeconds = 45,
  /// <summary>
  /// RUN. Triggers an on-demand LSE-vs-HSE ppm measurement (~250 ms). Result is cached and returned on the next GET TIME_DIAGNOSTICS.
  /// </summary>
  [pbr::OriginalName("TIME_DIAG_MEASURE_LSE")] TimeDiagMeasureLse = 46,
  /// <summary>
  /// RUN. Resets the boots_since_last_backup_loss counter to 0. Use after a deliberate battery replacement so the counter reflects only post-replacement boots.
  /// </summary>
  [pbr::OriginalName("BACKUP_DOMAIN_RESET_CANARY")] BackupDomainResetCanary = 47,
  /// <summary>
  /// GET-only. Returns the DALI system status summary (per-line online/fault device counts, bus-power errors, lowest faulting address, and missing/comms-error device bitmaps) — the same data the on-device Logic system evaluates for "any DALI error" actions. Use with the 'GET' AdminCommandType.
  /// </summary>
  [pbr::OriginalName("DALI_STATUS")] DaliStatus = 48,
  /// <summary>
  /// SET-only (ADMIN clearance). Provisions a role's login secret (see AdminUserAccountMessage). Write-only — secrets are never returned by a GET.
  /// </summary>
  [pbr::OriginalName("USER_ACCOUNT")] UserAccount = 49,
}

