/// <summary>
/// Refines an ERROR AckMessageType with a specific, machine-readable reason, carried in AckMessage.detail
/// (detail stays a uint32 - for SUCCESS / PARTIAL_SUCCESS it keeps its existing meaning, e.g. a line bitmask).
/// 0 = unspecified so older firmware (detail defaults to 0) gracefully degrades to the generic ack message.
/// The CLIENT owns the human-readable strings; this enum is the shared code&lt;->meaning contract so firmware and
/// app never drift. Values are allocated in 1000-wide blocks per subsystem - add new reasons to the owning
/// block, never renumber (gaps are free). uint32/varint: a value stays 2 wire-bytes up to 16383, and the field
/// itself reaches ~4.29e9, so the block scheme is effectively open-ended.
///   1-999       general / protocol (cross-cutting)
///   1000-1999   sensors
///   2000-2999   inputs
///   3000-3999   outputs
///   4000-4999   lists
///   5000-5999   schedules / alarms
///   6000-6999   zones
///   7000-7999   sequences / themes / colour
///   8000-8999   DALI commissioning / addressing
///   9000-9999   network / config
///   10000-10999 admin
///   11000-11999 firmware update / apply
/// </summary>
public enum RejectReason {
  /// <summary>
  /// No specific reason (older firmware, or a generic reject)
  /// </summary>
  [pbr::OriginalName("REJECT_UNSPECIFIED")] RejectUnspecified = 0,
  /// <summary>
  /// --- 1-999 general / protocol (cross-cutting) ---
  /// </summary>
  [pbr::OriginalName("GENERAL_REQUIRES_NEWER_FIRMWARE")] GeneralRequiresNewerFirmware = 1,
  /// <summary>
  /// Not supported on this hardware variant
  /// </summary>
  [pbr::OriginalName("GENERAL_UNSUPPORTED_ON_VARIANT")] GeneralUnsupportedOnVariant = 2,
  /// <summary>
  /// --- 1000-1999 sensors ---
  /// </summary>
  [pbr::OriginalName("SENSOR_BAD_LINE")] SensorBadLine = 1000,
  /// <summary>
  /// V4: sensor short address must be 0-63
  /// </summary>
  [pbr::OriginalName("SENSOR_ADDRESS_OUT_OF_RANGE")] SensorAddressOutOfRange = 1001,
  /// <summary>
  /// V4: control line mask falls outside the available lines
  /// </summary>
  [pbr::OriginalName("SENSOR_CONTROL_LINE_INVALID")] SensorControlLineInvalid = 1002,
  /// <summary>
  /// V4: control group/address is out of range
  /// </summary>
  [pbr::OriginalName("SENSOR_CONTROL_TARGET_INVALID")] SensorControlTargetInvalid = 1003,
  /// <summary>
  /// V8: a timer value would overflow once stored/scaled
  /// </summary>
  [pbr::OriginalName("SENSOR_TIMER_OUT_OF_RANGE")] SensorTimerOutOfRange = 1004,
  /// <summary>
  /// V7': non-zero legacy motion_sensors (an OLD client) - update the app
  /// </summary>
  [pbr::OriginalName("SENSOR_LEGACY_GROUPING")] SensorLegacyGrouping = 1005,
  /// <summary>
  /// V9: Leader role set without a cooperation group
  /// </summary>
  [pbr::OriginalName("SENSOR_LEADER_WITHOUT_GROUP")] SensorLeaderWithoutGroup = 1006,
  /// <summary>
  /// V9: cooperation group id is too large
  /// </summary>
  [pbr::OriginalName("SENSOR_GROUP_ID_INVALID")] SensorGroupIdInvalid = 1007,
  /// <summary>
  /// V1: a daylight-harvesting sensor must drive at least one line
  /// </summary>
  [pbr::OriginalName("SENSOR_HARVEST_NO_CONTROL_LINE")] SensorHarvestNoControlLine = 1008,
  /// <summary>
  /// V1: the harvesting seed query address must be a single 0-63 device
  /// </summary>
  [pbr::OriginalName("SENSOR_HARVEST_QUERY_ADDR_INVALID")] SensorHarvestQueryAddrInvalid = 1009,
  /// <summary>
  /// V1: the harvesting setpoint must be greater than 0
  /// </summary>
  [pbr::OriginalName("SENSOR_HARVEST_NO_SETPOINT")] SensorHarvestNoSetpoint = 1010,
  /// <summary>
  /// V2': ACTIVE members of one group must share the control target
  /// </summary>
  [pbr::OriginalName("SENSOR_GROUP_MIXED_TARGET")] SensorGroupMixedTarget = 1011,
  /// <summary>
  /// V10: another programmed sensor already uses this (short address, DALI line) - one physical sensor's events would drive multiple slots
  /// </summary>
  [pbr::OriginalName("SENSOR_DUPLICATE_ADDRESS")] SensorDuplicateAddress = 1012,
  /// <summary>
  /// --- 11000-11999 firmware update / apply (returned in an AckMessage(COMMAND_FAILED) reply to FW_APPLY) ---
  /// </summary>
  [pbr::OriginalName("FIRMWARE_APPLY_NO_IMAGE")] FirmwareApplyNoImage = 11000,
  /// <summary>
  /// Staged image failed the XOR checksum verify (corrupt or incomplete upload)
  /// </summary>
  [pbr::OriginalName("FIRMWARE_APPLY_CHECKSUM_FAILED")] FirmwareApplyChecksumFailed = 11001,
  /// <summary>
  /// Staged image geometry is not cleanly flashable (bad/misaligned chunk addressing) - would brick on handoff
  /// </summary>
  [pbr::OriginalName("FIRMWARE_APPLY_BAD_STRUCTURE")] FirmwareApplyBadStructure = 11002,
  /// <summary>
  /// No image signature was present - device rejects as unsigned
  /// </summary>
  [pbr::OriginalName("FIRMWARE_APPLY_UNSIGNED")] FirmwareApplyUnsigned = 11003,
  /// <summary>
  /// Image signature present but did not verify (wrong key, tampered, or content mismatch)
  /// </summary>
  [pbr::OriginalName("FIRMWARE_APPLY_SIGNATURE_INVALID")] FirmwareApplySignatureInvalid = 11004,
  /// <summary>
  /// A staged chunk could not be read back (blank/unreadable page) even after retries - the staged image is incomplete/corrupt in flash, NOT a geometry problem. Re-upload.
  /// </summary>
  [pbr::OriginalName("FIRMWARE_APPLY_INCOMPLETE")] FirmwareApplyIncomplete = 11005,
  /// <summary>
  /// Upload: the target page already held DIFFERENT data (the slot was not cleanly erased) - abort and restart the upload
  /// </summary>
  [pbr::OriginalName("FIRMWARE_UPLOAD_SLOT_NOT_ERASED")] FirmwareUploadSlotNotErased = 11006,
  /// <summary>
  /// Upload: the post-write read-back did not match what was sent (flash write did not take) - retry the chunk / upload
  /// </summary>
  [pbr::OriginalName("FIRMWARE_UPLOAD_WRITE_FAILED")] FirmwareUploadWriteFailed = 11007,
  /// <summary>
  /// Another connection already owns the firmware update session (single-owner) - wait for it to finish or disconnect, then retry
  /// </summary>
  [pbr::OriginalName("FIRMWARE_SESSION_BUSY")] FirmwareSessionBusy = 11008,
  /// <summary>
  /// V3: the image is encrypted but the device has no key to decrypt it - provision the device first
  /// </summary>
  [pbr::OriginalName("FIRMWARE_APPLY_NO_CONF_KEY")] FirmwareApplyNoConfKey = 11009,
  /// <summary>
  /// V3: image decryption failed - image not applied
  /// </summary>
  [pbr::OriginalName("FIRMWARE_APPLY_DECRYPT_FAILED")] FirmwareApplyDecryptFailed = 11010,
  /// <summary>
  /// The staged image needs a firmware format this device's bootloader cannot decode - provide a compatible image
  /// </summary>
  [pbr::OriginalName("FIRMWARE_APPLY_BOOTLOADER_INCOMPATIBLE")] FirmwareApplyBootloaderIncompatible = 11011,
}

